        static Sprite Sprite(string path){var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer){importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.maxTextureSize=256;importer.mipmapEnabled=false;importer.alphaIsTransparency=true;importer.SaveAndReimport();}return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
        static RectTransform Rect(Transform parent,string name,Vector2 anchor,float x,float y,float w,float h){var rect=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();rect.SetParent(parent,false);rect.anchorMin=rect.anchorMax=anchor;rect.pivot=new Vector2(0,1);rect.anchoredPosition=new Vector2(x,-y);rect.sizeDelta=new Vector2(w,h);return rect;}
        static RiftHUDGraphic Shape(Transform p,string n,HUDShape s,float x,float y,float w,float h){var g=Rect(p,n,new Vector2(0,1),x,y,w,h).gameObject.AddComponent<RiftHUDGraphic>();g.Shape=s;g.Border=theme.Gold;g.color=Color.white;g.raycastTarget=false;return g;}
        static Text Label(Transform p,string t,float x,float y,float w,float h,int size,bool title=false){var label=Rect(p,t,new Vector2(0,1),x,y,w,h).gameObject.AddComponent<Text>();label.text=t;label.font=title&&theme.TitleFont?theme.TitleFont:theme.BodyFont;label.fontSize=size;label.color=theme.Text;label.raycastTarget=false;label.horizontalOverflow=HorizontalWrapMode.Overflow;label.verticalOverflow=VerticalWrapMode.Overflow;return label;}
        static void Rule(Transform p,float x,float y,float w){var g=Shape(p,"Fine gold rule",HUDShape.Line,x,y,w,1);g.color=theme.Gold;}
        static RiftHUDGraphic Bar(Transform p,string n,float x,float y,float w,float h,Color color){Shape(p,n+" frame",HUDShape.Bar,x,y,w,h);var fill=Shape(p,n+" fill",HUDShape.Bar,x+2,y+2,w-4,h-4);fill.color=color;fill.Bottom=color*.65f;fill.Thickness=0;return fill;}
        static void RenderPortrait(string path)
        {
            var scene=EditorSceneManager.NewPreviewScene();var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ROM/Characters/Warrior/WarriorLobby.prefab");var model=UnityEngine.Object.Instantiate(source);SceneManagementMove(model,scene);model.transform.position=Vector3.zero;model.transform.rotation=Quaternion.Euler(0,180,0);foreach(var a in model.GetComponentsInChildren<Animator>())a.enabled=false;var bounds=new Bounds(model.transform.position,Vector3.zero);foreach(var r in model.GetComponentsInChildren<Renderer>())bounds.Encapsulate(r.bounds);
            var cam=new GameObject("Portrait camera").AddComponent<Camera>();SceneManagementMove(cam.gameObject,scene);cam.scene=scene;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.03f,.025f,.04f,1);cam.fieldOfView=28;cam.transform.position=new Vector3(0,bounds.max.y-.4f,-2.1f);cam.transform.LookAt(new Vector3(0,bounds.max.y-.4f,0));var light=new GameObject("Portrait key").AddComponent<Light>();SceneManagementMove(light.gameObject,scene);light.type=LightType.Directional;light.intensity=2;light.transform.rotation=Quaternion.Euler(35,155,0);var rt=new RenderTexture(256,320,24);cam.targetTexture=rt;cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(256,320,TextureFormat.RGBA32,false);tex.ReadPixels(new Rect(0,0,256,320),0,0);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());RenderTexture.active=old;cam.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);EditorSceneManager.ClosePreviewScene(scene);AssetDatabase.ImportAsset(path);
        }
